using System.Threading.Tasks;

public class Program
{
    public static void Main(string[] args)
    {
        int n = int.Parse(args[0]);
        if (n < 1)
        {
            Console.WriteLine("0");
            Console.WriteLine("Pfannkuchen(0) = 0");
            return;
        }

        // Parallel fannkuch-redux with chunked permutation-index ranges.
        long totalPerms = 1;
        for (int i = 2; i <= n; i++) totalPerms *= i;

        int processors = Environment.ProcessorCount;
        long chunkSize = Math.Max(1, totalPerms / (processors * 8L));
        long chunkCount = (totalPerms + chunkSize - 1) / chunkSize;

        object gate = new object();
        long globalChecksum = 0;
        int globalMaxFlips = 0;

        Parallel.For(0L, chunkCount, () => (checksum: 0L, maxFlips: 0),
            (chunkIndex, state, local) =>
            {
                long startIndex = chunkIndex * chunkSize;
                long endIndex = Math.Min(totalPerms, startIndex + chunkSize);

                int[] perm = new int[n];
                int[] count = new int[n];

                // Convert permutation index to factoradic / Lehmer code, then generate permutation.
                for (long idx = startIndex; idx < endIndex; idx++)
                {
                    long x = idx;
                    for (int i = 0; i < n; i++) count[i] = 0;
                    for (int i = 1; i <= n; i++)
                    {
                        count[n - i] = (int)(x % i);
                        x /= i;
                    }

                    for (int i = 0; i < n; i++) perm[i] = i + 1;
                    for (int i = 0; i < n; i++)
                    {
                        int c = count[i];
                        if (c != 0)
                        {
                            int tmp = perm[i];
                            perm[i] = perm[i + c];
                            perm[i + c] = tmp;
                        }
                    }

                    int flips = 0;
                    int first = perm[0];
                    while (first != 1)
                    {
                        Array.Reverse(perm, 0, first);
                        flips++;
                        first = perm[0];
                    }

                    if (flips > local.maxFlips) local.maxFlips = flips;
                    if ((idx & 1) == 0) local.checksum += flips;
                    else local.checksum -= flips;
