                    globalChecksum += local.checksum;
                    if (local.maxFlips > globalMaxFlips) globalMaxFlips = local.maxFlips;
                }
            });

        Console.WriteLine(globalChecksum);
        Console.WriteLine($"Pfannkuchen({n}) = {globalMaxFlips}");
    }
