using System.IO;
using System.Text;

public static class Program
{
    private static readonly string[] Fragments =
    {
        "GGT",
        "GGTA",
        "GGTATT",
        "GGTATTTTAATT",
        "GGTATTTTAATTTATAGT"
    };

    public static void Main(string[] args)
    {
        string input = Console.In.ReadToEnd();
        string seq = ParseFastaSequence(input);

        var sb = new StringBuilder();

        AppendFrequencies(sb, seq, 1);
        sb.Append('\n');
        AppendFrequencies(sb, seq, 2);
        sb.Append('\n');
        AppendFragmentCounts(sb, seq);

        Console.Write(sb.ToString());
    }

    private static string ParseFastaSequence(string input)
    {
        var sb = new StringBuilder(input.Length);
        using var reader = new StringReader(input);
        string? line;
        while ((line = reader.ReadLine()) != null)
        {
            if (line.Length > 0 && line[0] == '>')
                continue;

            for (int i = 0; i < line.Length; i++)
            {
                char c = line[i];
                if (c >= 'a' && c <= 'z') c = (char)(c - 32);
                if (c == 'A' || c == 'C' || c == 'G' || c == 'T')
                    sb.Append(c);
            }
        }
        return sb.ToString();
    }

    private static void AppendFrequencies(StringBuilder sb, string seq, int k)
    {
        int len = seq.Length;
        int size = 1 << (2 * k);
        int[] counts = new int[size];

        int mask = size - 1;
        int bits = 0;
        int seen = 0;

        for (int i = 0; i < len; i++)
        {
            bits = ((bits << 2) | Encode(seq[i])) & mask;
            if (seen < k - 1)
            {
                seen++;
                continue;
            }
            counts[bits]++;
        }

        int total = len - k + 1;
        var entries = new List<(int Key, int Count)>();
        for (int i = 0; i < size; i++)
        {
            if (counts[i] > 0)
                entries.Add((i, counts[i]));
        }

        entries.Sort((a, b) =>
        {
            int cmp = b.Count.CompareTo(a.Count);
            return cmp != 0 ? cmp : a.Key.CompareTo(b.Key);
        });

        foreach (var e in entries)
        {
            sb.Append(FormatKmer(e.Key, k));
            sb.Append(' ');
            sb.Append((e.Count * 100.0 / total).ToString("F3", System.Globalization.CultureInfo.InvariantCulture));
            sb.Append('\n');
        }
    }

    private static void AppendFragmentCounts(StringBuilder sb, string seq)
    {
        foreach (var frag in Fragments)
        {
            sb.Append(CountOccurrences(seq, frag));
            sb.Append('\t');
            sb.Append(frag);
            sb.Append('\n');
        }
    }

    private static int CountOccurrences(string text, string pattern)
    {
        int count = 0;
        int n = text.Length;
        int m = pattern.Length;
        if (m == 0 || n < m) return 0;

        for (int i = 0; i <= n - m; i++)
        {
            int j = 0;
            while (j < m && text[i + j] == pattern[j]) j++;
            if (j == m) count++;
        }
        return count;
    }

    private static int Encode(char c)
    {
        return c switch
        {
            'A' => 0,
            'C' => 1,
            'G' => 2,
            'T' => 3,
            _ => 0
        };
    }

    private static string FormatKmer(int code, int k)
    {
        char[] chars = new char[k];
        for (int i = k - 1; i >= 0; i--)
        {
            chars[i] = Decode(code & 3);
            code >>= 2;
        }
        return new string(chars);
    }

    private static char Decode(int x)
    {
        return x switch
        {
            0 => 'A',
            1 => 'C',
            2 => 'G',
            3 => 'T',
            _ => 'A'
        };
    }
}
