using System.Threading.Tasks;

public static class Program
{
    public static void Main(string[] args)
    {
        int n = int.Parse(args[0]);

        var stdout = Console.OpenStandardOutput();
        using var writer = new BufferedStream(stdout, 1 << 16);

        // PBM header: "P4\n<width> <height>\n"
        WriteAscii(writer, "P4\n");
        WriteAscii(writer, n.ToString());
        WriteAscii(writer, " ");
        WriteAscii(writer, n.ToString());
        WriteAscii(writer, "\n");

        int bytesPerRow = (n + 7) >> 3;
        byte[] row = new byte[bytesPerRow];

        // Mandelbrot region: x in [-2.0, 1.0], y in [-1.5, 1.5]
        double scaleX = 3.0 / n;
        double scaleY = 3.0 / n;

        for (int py = 0; py < n; py++)
        {
            Array.Clear(row, 0, row.Length);
            double cy = py * scaleY - 1.5;

            for (int px = 0; px < n; px++)
            {
                double cx = px * scaleX - 2.0;

                double x = 0.0, y = 0.0;
                int iter = 0;
                while (iter < 50)
                {
                    double xx = x * x - y * y + cx;
                    double yy = 2.0 * x * y + cy;
                    x = xx;
                    y = yy;
                    if (x * x + y * y > 4.0) break;
                    iter++;
                }

                if (iter == 50)
                {
                    int idx = px >> 3;
                    int bit = 7 - (px & 7);
                    row[idx] |= (byte)(1 << bit);
                }
            }

            writer.Write(row, 0, row.Length);
        }

        writer.Flush();
    }

    private static void WriteAscii(Stream s, string text)
    {
        byte[] bytes = Encoding.ASCII.GetBytes(text);
        s.Write(bytes, 0, bytes.Length);
    }
