        string substituted = Regex.Replace(stripped, "tHa[Nt]", "<4>");
        substituted = Regex.Replace(substituted, "aND|caN|Ha[DS]|WaS", "<3>");
        substituted = Regex.Replace(substituted, "a[NSt]|BY", "<2>");
        substituted = Regex.Replace(substituted, "<[^>]*>", "|");
        substituted = Regex.Replace(substituted, "\\|[^|][^|]*\\|", "-");

        sb.Append('\n');
        sb.Append(originalLength).Append('\n');
        sb.Append(strippedLength).Append('\n');
        sb.Append(substituted.Length).Append('\n');

        Console.Write(sb.ToString());
    }
}
